def transform(grid):
    rows, cols = len(grid), len(grid[0])
    outer = flood_fill_outer(grid)
    enclosed = {(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 0 and (r,c) not in outer}

    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                result[r][c] = 1
            elif (r, c) in enclosed:
                # Interior 0
                # Check if adjacent to any 1
                has_one_adjacent = False
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                        has_one_adjacent = True
                        break
                if has_one_adjacent:
                    result[r][c] = 3
                else:
                    result[r][c] = 0  # Like (3,3)
            else:
                # Exterior 0
                # Adjacent to 1 → 2
                # Otherwise, maybe 0 (corners?)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                        result[r][c] = 2
                        break
                else:
                    # Not adjacent to 1
                    result[r][c] = 2  # Default for now
