    pairs = json.load(f)

def solve_pair0(grid):
    """
    Transform pair 0 rule:
    - Background (0) connected to grid edge becomes 2
    - Background (0) "inside" closed shape becomes 3
    - Shape (1) stays 1
    """
    h, w = len(grid), len(grid[0])

    # Mark connected-to-edge (background on boundary)
    boundary = {}
    for r in range(h - 1, -1, -1):
        for c in range(w - 1, -1, -1):
            if grid[r][c] == 0:
                boundary[(r, c)] = True

    # Actually let's do BFS from edges to find all background reachable from edges
    out = [[0]*w for _ in range(h)]

    # Find all edge-connected background
    edgears = set()
    for r in range(h):
        for c in [0, w-1]:
            if grid[r][c] == 0:
                edgears.add((r, c))
    for c in range(w):
        for r in [0, h-1]:
            if grid[r][c] == 0:
                edgears.add((r, c))

    # BFS from edge-connected background
    stack = list(edgears)
    while stack:
        r, c = stack.pop()
        out[r][c] = 2

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == 0 and (nr, nc) not in out:
                    out[nr][nc] = 2
                    stack.append((nr, nc))

    # Now find "interior" background (0) that wasn't reached - these are holes
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and out[r][c] == 0:
                out[r][c] = 3

    return out

